protocol Greeter { var name: String { get } }
extension Greeter {
    func greet() { print("Hi, \(name)") }
}
struct User: Greeter { let name = "Mina" }
User().greet()

protocol Shape { func describe() -> String }
extension Shape {
    func describe() -> String { "A shape" }
}
struct Square: Shape {}
print(Square().describe())

protocol Box {
    associatedtype Item
    var item: Item { get }
}
struct IntBox: Box { let item = 7 }
print(IntBox().item)

